import{_ as e,o as i,c as l,ae as t}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Cloud Backup and Sync","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/06-cloud-backup-guide.md","filePath":"v1/en/guide/06-cloud-backup-guide.md"}'),n={name:"v1/en/guide/06-cloud-backup-guide.md"};function o(s,a,c,r,u,d){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="cloud-backup-and-sync" tabindex="-1">Cloud Backup and Sync <a class="header-anchor" href="#cloud-backup-and-sync" aria-label="Permalink to &quot;Cloud Backup and Sync&quot;">​</a></h1><h2 id="📋-overview" tabindex="-1">📋 Overview <a class="header-anchor" href="#📋-overview" aria-label="Permalink to &quot;📋 Overview&quot;">​</a></h2><p>Expense Tracker: Koala (“Koala”) provides cloud backup so your bills can be synced across devices when you sign in with the same account.</p><hr><h2 id="☁️-what-is-cloud-backup" tabindex="-1">☁️ What is cloud backup? <a class="header-anchor" href="#☁️-what-is-cloud-backup" aria-label="Permalink to &quot;☁️ What is cloud backup?&quot;">​</a></h2><p>Cloud backup uploads your data to the server to support:</p><ul><li>Data safety (device loss or damage)</li><li>Multi-device sync</li><li>Restoring data on a new device</li></ul><blockquote><p>💡 Tips:</p><ul><li>Cloud backup requires signing in (currently supports Sign in with Apple).</li><li>Access control and data isolation are applied so only you can access your data.</li><li>Most syncing is automatic; you can also trigger it manually.</li></ul></blockquote><hr><h2 id="🔐-sign-in-apple" tabindex="-1">🔐 Sign in (Apple) <a class="header-anchor" href="#🔐-sign-in-apple" aria-label="Permalink to &quot;🔐 Sign in (Apple)&quot;">​</a></h2><ol><li>Open Expense Tracker: Koala and go to <strong>Settings</strong></li><li>Tap the user card at the top</li><li>Tap <strong>Sign in with Apple</strong> and follow the prompts</li></ol><hr><h2 id="🔄-sync-behavior" tabindex="-1">🔄 Sync behavior <a class="header-anchor" href="#🔄-sync-behavior" aria-label="Permalink to &quot;🔄 Sync behavior&quot;">​</a></h2><h3 id="automatic-sync" tabindex="-1">Automatic sync <a class="header-anchor" href="#automatic-sync" aria-label="Permalink to &quot;Automatic sync&quot;">​</a></h3><p>Koala syncs automatically in cases like:</p><ul><li>App launch (sync accounts and ledgers)</li><li>After data changes (create, edit, delete bills)</li><li>When switching ledgers (silently sync the current ledger data)</li></ul><h3 id="manual-sync" tabindex="-1">Manual sync <a class="header-anchor" href="#manual-sync" aria-label="Permalink to &quot;Manual sync&quot;">​</a></h3><ol><li>Open <strong>Settings</strong></li><li>Tap the cloud icon (top-right)</li><li>Keep the app in the foreground until it finishes</li></ol><hr><h2 id="📊-what-is-synced" tabindex="-1">📊 What is synced <a class="header-anchor" href="#📊-what-is-synced" aria-label="Permalink to &quot;📊 What is synced&quot;">​</a></h2><ul><li>Ledgers</li><li>Bills</li><li>Accounts</li><li>Categories</li><li>Tags</li></ul><p>Not synced:</p><ul><li>App settings (theme and language)</li><li>Cache data</li><li>Personal preferences</li></ul><hr><h2 id="🔄-conflicts" tabindex="-1">🔄 Conflicts <a class="header-anchor" href="#🔄-conflicts" aria-label="Permalink to &quot;🔄 Conflicts&quot;">​</a></h2><ul><li>If a record has local changes that have not been uploaded, Koala keeps the local changes to avoid being overwritten.</li><li>When both sides change the same record, Koala tries to keep the most recent change.</li></ul><hr><p><strong>Last updated</strong>: May 2026</p>',28)])])}const g=e(n,[["render",o]]);export{p as __pageData,g as default};
